mapper.select:
select f.file_relation_id as fileRelationId,
sec.Sec_Name as secName, con.Con_Name as conName, pd.Pmd_Title as pmdTitle, pd.Pmd_Type as pmdType, pd.Pmd_Content as pmdContent, mn.* from OA_Problem_Feedback mn left join OA_Problem_Dtl pd on pd.Pmd_Id=mn.Pmd_Id left join OA_Problem op on op.Pm_Id=pd.Pm_Id left join Pre_Project pro on pro.P_Id=op.P_Id
left join Sec_Info sec on sec.Sec_Id=op.Sec_Id left join Con_Contract con on con.Con_Id=op.Con_Id left join Sys_File f on f.FileID=mn.Pmf_Id where mn.Pmd_Id=#{pmdId}

select
sec.Sec_Name as secName, con.Con_Name as conName, pd.Pmd_Title as pmdTitle, pd.Pmd_Type as pmdType, pd.Pmd_Content as pmdContent, mn.* from OA_Problem_Feedback mn left join OA_Problem_Dtl pd on pd.Pmd_Id=mn.Pmd_Id left join OA_Problem op on op.Pm_Id=pd.Pm_Id left join Pre_Project pro on pro.P_Id=op.P_Id
left join Sec_Info sec on sec.Sec_Id=op.Sec_Id left join Con_Contract con on con.Con_Id=op.Con_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pmf_Create_Time desc
